INSERT INTO INT_SERVERFUNCTION (ID, NAME, DESCRIPTION, TYPE, CODE, JDBC_ID, PUBLIC_EXECUTION, CRON_EXPRESSION, CRON_INPUT_JSON, CREATED_BY) VALUES (130, 'hotGestoresBase', 'Mount de Gestores em 1 ida (CRS,GESTOR_CRS,GESTOR_PACOTES,PACOTES). Sem params.', 'SQL', 'SELECT
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',t.ID,''CODIGO'',t.CODIGO,''NOME'',t.NOME,''EMPRESA_ID'',t.EMPRESA_ID,''ATIVO'',t.ATIVO)) FROM CENTRO_RESULTADO t WHERE t.ATIVO = ''true''),JSON_ARRAY()) AS CRS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',gc.ID,''GESTOR_ID'',gc.GESTOR_ID,''CR_ID'',gc.CR_ID,''CODIGO'',cr.CODIGO,''CR_NOME'',cr.NOME)) FROM GESTOR_CR gc JOIN CENTRO_RESULTADO cr ON cr.ID = gc.CR_ID),JSON_ARRAY()) AS GESTOR_CRS,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''GESTOR_ID'',gp.GESTOR_ID,''ID'',gp.ID,''DRIVER_NOME'',d.NOME,''DRIVER_ID'',d.ID)) FROM GESTOR_PACOTE gp JOIN DRIVERS d ON d.ID = gp.DRIVER_ID AND d.ATIVO = ''true'' AND d.TIPO_DRIVER = ''PACOTE''),JSON_ARRAY()) AS GESTOR_PACOTES,
  COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT(''ID'',d.ID,''NOME'',d.NOME)) FROM DRIVERS d WHERE d.ATIVO = ''true'' AND d.TIPO_DRIVER = ''PACOTE''),JSON_ARRAY()) AS PACOTES', NULL, FALSE, NULL, NULL, 'sarah@mitralab.io');
